package com.kk.str;

/**
 * KMP字符串匹配算法
 */
public class KMP {
    public static int find(String str, String temp) {
<COVER>        return find(str.toCharArray(), temp.toCharArray());
    }

    public static int find(char[] str, char[] temp) {
<COVER>        int n = str.length;

<COVER>        int tempLen = temp.length;

<COVER>        int[] jumpTable = calJumpTable(temp);

<COVER>        int j = 0; //j表示当前模版串的待匹配位置

<COVER>        for (int i = 0; i < n; ++i) {
<COVER>            while (str[i] != temp[j]) { // 失配点
<COVER>                j = jumpTable[j]; //不停的转移，直到可以匹配或者走到0

<COVER>                if (j == 0) break;
            }

            // 调整失配点之后，向后移位逐个比较
<COVER>            if (str[i] == temp[j]) j++;

<COVER>            if (j == tempLen) return i - tempLen + 1;
        }

        // 未找到
        return -1;
    }

    static int[] calJumpTable(String temp) {
        return calJumpTable(temp.toCharArray());
    }

    /**
     * 计算失配-跳转表
     */
    static int[] calJumpTable(char[] temp) {
<COVER>        int len = temp.length;
<COVER>        int[] table = new int[len + 1];

<COVER>        table[0] = table[1] = 0; // 边界

<COVER>        for (int n = 1; n < len; ++n) {
<COVER>            int jump = table[n];

<COVER>            while (temp[n] != temp[jump]) {
                // jump 向前追溯
<COVER>                jump = table[jump];

<COVER>                if (jump == 0) { // 为0，表示已回退到指定点
<COVER>                    break;
                }
            }

            // 递推
<COVER>            table[n + 1] = temp[n] == temp[jump] ? jump + 1 : 0;
        }

<COVER>        return table;
    }
}

