        builder.append("SingleLinkedList[");

        foreach((node, id) -> {
            if (id == 0) {
                builder.append(node.val);
            } else {
                builder.append("-->" + node.val);
            }

            return true;
        });

        builder.append("]");
        return builder.toString();
    }
