import java.util.Random;

/**
 * 跳表
 */
public class SkipList {
    // 最高层的头尾节点
    public SkipListEntry head;
    public SkipListEntry tail;

    // 高度
    public int height;
    // 0层总节点数
    public int size;

    public Random random;    // Coin toss

<COVER>    public SkipList() {
        // 创建一个 -oo 和一个 +oo 对象
<COVER>        head = new SkipListEntry(SkipListEntry.INFINITE_NEGATIVE, null);
<COVER>        tail = new SkipListEntry(SkipListEntry.INFINITE_POSITIVE, null);

        // 将 -oo 和 +oo 相互连接
<COVER>        head.right = tail;
<COVER>        tail.left = head;

<COVER>        size = 0;
<COVER>        height = 0;
<COVER>        random = new Random();
