<COVER>        SkipListEntry toPutEntry = insertByClockwise(key, value, prev);

        // 向上跳跃的高度
<COVER>        int jumpHeight = 0;

        // 再使用随机数决定是否要向更高level攀升
<COVER>        while (random.nextDouble() < 0.5) {
            // 如果新元素的级别已经达到跳跃表的最大高度，则新建空白层
<COVER>            if (jumpHeight >= height) {
<COVER>                addEmptyLevel();
            }

            // 从该层前驱节点向左查询和上层关联的前驱节点
<COVER>            prev = jumpUp(prev);

