     */
    private SkipListEntry insertByClockwise(String key, Integer value, SkipListEntry prev) {
<COVER>        SkipListEntry toPutEntry = new SkipListEntry(key, value);

        // 后继节点
<COVER>        SkipListEntry suceed = prev.right;
        // 指向后继
<COVER>        toPutEntry.right = suceed;
        // 后继指向该节点
<COVER>        suceed.left = toPutEntry;
        // 指向前驱
<COVER>        toPutEntry.left = prev;
        // 前驱指向该节点
<COVER>        prev.right = toPutEntry;

<COVER>        return toPutEntry;
    }

    /**
     * 新值空白层
     */
    private void addEmptyLevel() {
        SkipListEntry newHead, newTail;

<COVER>        newHead = new SkipListEntry(SkipListEntry.INFINITE_NEGATIVE, null);
<COVER>        newTail = new SkipListEntry(SkipListEntry.INFINITE_POSITIVE, null);

<COVER>        newHead.right = newTail;
<COVER>        newTail.left = newHead;

        // 上下层关联
<COVER>        newHead.down = head;
<COVER>        newTail.down = tail;
<COVER>        head.up = newHead;
<COVER>        tail.up = newTail;

        // 更新最高层头尾
<COVER>        head = newHead;
<COVER>        tail = newTail;

<COVER>        height = height + 1;
    }

    /**
     * 剔除某个key
     */
    public Integer remove(String key) {
        SkipListEntry found;

        found = findEntry(key);

        if (!found.key.equals(key)) { // key不匹配，说明是前驱节点，没有改key的节点
            return null;
        }

        Integer oldValue = found.value;

        while (found != null) {
            // 对应的上传索引节点
            SkipListEntry upIndex = found.up;

            // 前驱和后继直接关联
            SkipListEntry prev = found.left;
            SkipListEntry succeed = found.right;
            prev.right = succeed;
            succeed.left = prev;

            found = upIndex;
        }

        return oldValue;
    }

    /**
     * 从上、往下遍历每个层的所有节点
     */
    public void foreach(EntryConsumer consumer) {
        if (size == 0) {
            return;
        }

        SkipListEntry levelHead = head;
        SkipListEntry cursor = levelHead;

        for (int level = height; level >= 0; level--) {  // 外层控制遍历的层级，从上往下层遍历
            int pos = 0;

            while (cursor.right != null) {
                if (!isEndpoint(cursor)) {
                    if (null != consumer && !consumer.item(level, pos, cursor)) {
                        return;
                    }

                    pos++;
                }

                cursor = cursor.right;
            }

            // 记录下层头节点
            cursor = levelHead = levelHead.down;
        }
    }

    /**
     * 判断一个节点是否是终端节点（头、尾）节点
     */
    private boolean isEndpoint(SkipListEntry entry) {
        return entry.key.equals(SkipListEntry.INFINITE_NEGATIVE) || entry.key.equals(SkipListEntry.INFINITE_POSITIVE);
    }

    @Override
    public String toString() {
        StringBuilder builder = new StringBuilder();

        final int[] lastLevel = {height};

        foreach((EntryConsumer) (level, pos, entry) -> {
            if (level != lastLevel[0]) {
                lastLevel[0] = level;
                builder.append("\n");
            }

            builder.append("-->" + entry.key);

            return true;
        });

        return builder.toString();
    }
}

