            RedBlackNode broRight = brother.right;

            if (broRight != null && broRight.isRed()) { // 兄右红
                linkToParent(parent, leftRotate(brother)); // -> 以兄左旋
                brother.toBlack(); // 黑色
                linkToParent(parent.parent, rightRotate(parent)); // 父右旋
