     */
    public void linkToParent(RedBlackNode parent, RedBlackNode child) {
        if (null == parent) {
            root = child;
            root.parent = null;
            return;
        }

        boolean isLarger = parent.key.compareTo(child.key) > 0;

        if (isLarger) {
