package com.kk.datastructure.tree2.huffman;

import java.util.PriorityQueue;


/**
 * Huffman树
 */
<COVER>public class HuffmanTree {
<COVER>    int size = 0;
    Node root;

    // 记录所有的叶子节点，无需再遍历得到
<COVER>    PriorityQueue<Node> leafs = new PriorityQueue<>();

    /**
     * 存入多个节点
     */
    public void put(Node... nodes) {
        // 入队列排序
<COVER>        PriorityQueue<Node> queue = new PriorityQueue<>(nodes.length);

<COVER>        if (null != root) {
            queue.add(root);
        }

<COVER>        for (Node node : nodes) {
<COVER>            queue.add(node);
<COVER>            leafs.add(node);
<COVER>            size++;
        }

        // 不断取出最小的2个值组合一个父节点，直到队列为空
<COVER>        while (queue.size() != 1) {
<COVER>            Node first = queue.poll();
<COVER>            Node second = queue.poll();

            // 合并得到一个父节点
<COVER>            createParent(first, second);

<COVER>            queue.add(root);
        }
    }

    private void createParent(Node first, Node second) {
<COVER>        root = new Node(first.weight + second.weight);
<COVER>        root.left = first;
<COVER>        root.right = second;

<COVER>        first.parent = root;
<COVER>        second.parent = root;
    }

    /**
     * 计算最短路径长度
     */
    int wpl() {
<COVER>        int wpl = 0;

<COVER>        for (Node leaf : leafs) {
<COVER>            int depth = depthForLeaf(leaf);
<COVER>            wpl += leaf.weight * depth;
        }

<COVER>        return wpl;
    }

    /**
     * 获取一个叶子的深度
     */
    int depthForLeaf(Node node) {
<COVER>        int depath = 0;

<COVER>        while (node.parent != null) { // 不断向上判断父节点
<COVER>            depath++;
<COVER>            node = node.parent;
        }

<COVER>        return depath;
    }
}

